SELECT MAX(COALESCE(json_extract(p.payload,'$.amount'), json_extract(p.payload,'$.amount_cents')/100.0,
  json_extract(p.payload,'$.charges.data[0].amount_cents')/100.0, CAST(json_extract(p.payload,'$.transaction.value.amount') AS REAL))) FROM payment_events p WHERE LOWER(COALESCE(json_extract(p.payload,'$.status'), json_extract(p.payload,'$.state'), json_extract(p.payload,'$.transaction.result.status')))='succeeded' AND UPPER(COALESCE(json_extract(p.payload,'$.currency'), json_extract(p.payload,'$.currency_code'), json_extract(p.payload,'$.transaction.value.currency')))='USD'
